const chatId = $('Webhook Commands').item.json.body.senderData.chatId;
const userData = $json;

const remaining = userData.remaining_analyses || 0;
const tier = userData.tier || 'free';
const maxPages = userData.max_pages || 3;

const tierEmoji = {
  'free': '🆓',
  'basic': '💎',
  'premium': '👑'
};

const balanceMessage = `${tierEmoji[tier]} *Ваш баланс*\n\n` +
  `📊 Тариф: ${tier.toUpperCase()}\n` +
  `📄 Осталось анализов: *${remaining}*\n` +
  `📑 Макс. страниц: ${maxPages}\n\n` +
  (remaining === 0 ? 
    `❌ Анализы закончились\n\n💰 Купить еще: /pay` :
    `✅ Можете анализировать документы!\n\n📤 Отправьте PDF или DOCX файл для анализа`);

return [{
  json: {
    chatId: chatId,
    message: balanceMessage
  }
}];

const chatId = $json.body.senderData.chatId;

const paymentMessage = `💳 *Тарифные пакеты*\n\n` +
  `📦 *ПАКЕТ 5 АНАЛИЗОВ - 2990 ₸*\n` +
  `   • До 10 страниц\n` +
  `   • Базовый анализ рисков\n` +
  `   • Срок: 1 месяц\n\n` +

  `📦 *ПАКЕТ 10 АНАЛИЗОВ - 4990 ₸*\n` +
  `   • До 10 страниц\n` +
  `   • Базовый анализ\n` +
  `   • Выгода: 1000₸\n` +
  `   • Срок: 2 месяца\n\n` +

  `📦 *ПАКЕТ 20 АНАЛИЗОВ - 7990 ₸*\n` +
  `   • До 15 страниц\n` +
  `   • Расширенный анализ\n` +
  `   • Сравнение версий\n` +
  `   • Протокол разногласий\n` +
  `   • Выгода: 3990₸\n` +
  `   • Срок: 3 месяца\n\n` +

  `🔗 *Для оплаты:*\n` +
  `Нажмите на кнопку ниже или переведите на Kaspi:\n` +
  `+7 (XXX) XXX-XX-XX\n` +
  `Комментарий: AI-Lawyer ${chatId}\n\n` +
  `После оплаты пришлите скриншот чека.`;

return [{
  json: {
    chatId: chatId,
    message: paymentMessage,
    keyboard: {
      inline_keyboard: [
        [
          { text: '📦 5 анализов - 2990₸', callback_data: 'buy_pack_5' },
          { text: '📦 10 анализов - 4990₸', callback_data: 'buy_pack_10' }
        ],
        [
          { text: '👑 20 анализов - 7990₸', callback_data: 'buy_pack_20' }
        ],
        [
          { text: '💳 Kaspi оплата', url: 'https://kaspi.kz/pay/XXXXXX' }
        ]
      ]
    }
  }
}];
